    return regex.test(phone, "^\\+1\\d{10}$")
}

to_e164 = fun(phone) {
    digits = regex.replace(phone, "[^0-9]", "")
    normalized = if text.starts_with(digits, "1") and text.length(digits) == 11 {
        return digits
    } else if text.length(digits) == 10 {
        return "1" + digits
    } else {
        return digits
    }
    return "+" + normalized
}

results = for contact in contacts {
    needs_phone = contact.phone != null and not regex.test(contact.phone, "^\\+1\\d{10}$")
    new_phone = to_e164(contact.phone) if needs_phone else null

    email = contact.email if contact.email != null else ""
    parts = text.split(email, "@")
    domain = parts[1] if list.length(parts) == 2 else ""
    needs_company = (contact.company == null or contact.company == "") and domain != "" and domain in domain_to_company
    new_company = domain_to_company[domain] if needs_company else null

    updated = null
    if needs_phone or needs_company {
        updated = boundary retry 2 {
            return update_contact({
                id: contact.id,
                phone: new_phone if needs_phone else null,
                company: new_company if needs_company else null
            })
        } catch err {
            return fail("UPDATE_FAILED", err.code + ": " + err.message)
        }
    }

    return {
        phone_fixed: needs_phone,
        company_filled: needs_company
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, recorded: submit.recorded }

